import{z as r,x as s,o as a,c as A,q as o,j as n,D as E,d as i,s as B,S as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"inode 与目录","description":"","frontmatter":{"title":"inode 与目录","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inode-dir.md","filePath":"cs/inode-dir.md","lastUpdated":1791413859000}'),l={name:"cs/inode-dir.md"};function c(p,e,m,D,_,h){const d=s("Mermaid");return a(),A("div",null,[e[2]||(e[2]=o('<h1 id="inode-与目录" tabindex="-1">inode 与目录 <a class="header-anchor" href="#inode-与目录" aria-label="Permalink to &quot;inode 与目录&quot;">​</a></h1><div class="epigraph"><p>inode 记下类型、权限、块指针；目录只是把名字映射到 inode 号的文件。</p><footer>—— 据 Thompson, UNIX Implementation；Bach, The Design of the UNIX Operating System 整理</footer></div><p><a href="/cs/dcache">上一课</a>让描述符对着字节流，路径还是字符串。缺口是持久编号：<strong>inode</strong> 持有元数据与块地址，目录把分量名译成 inode 号。本课不把脏缓冲与磁盘臂调度写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若字节流的元数据跟名字绑死，硬链接无法存在：两个名字无法共享同一份块指针。Unix 把「是什么」放进 inode，「叫什么」放进目录项。缺口不是再定义 <code>read</code>，而是：路径查找沿目录 inode 走，最后落到目标 inode；打开后描述符抓住 inode（或指向它的打开文件），改名不影响已打开的流。</p><p><span class="marginnote">直觉类比：硬链接像同一间房开的两扇门——拆掉一扇门，房子还在；inode 里的链接计数就是「门的数量」。符号链接则像门上贴的一张「请去隔壁找」的纸条，隔壁真拆了，纸条就成了悬空引用。</span></p><p>本课不把现代目录的 B+ 树当唯一实现；经典线性目录足够讲清对象。</p><p><span class="marginnote">inode 含类型（普通、目录、符号链接、设备）、链接计数、时间、权限、大小、直接/间接块指针。链接计数为零且无打开者才回收块。</span></p><p><span class="marginnote">数字实例：<code>ln a b</code> 之后，inode 的链接计数从 1 变 2；<code>rm a</code> 只是把它减回 1，数据一个字节都没动——<code>b</code> 照常能读。要再 <code>rm b</code>，计数归零，块才进入回收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路径 <code>/a/b</code>：从根 inode 读目录文件，找 <code>a</code> 得目录 inode，再找 <code>b</code>。<code>.</code> 与 <code>..</code> 是目录里的项。硬链接：多条目录项同一 inode 号，计数加一。符号链接是存路径的小文件，查找时再解析。权限在每一层目录与最后 inode 上检查。</p>',11)),(a(),n(t,null,{default:E(()=>[B(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E8%B7%AF%E5%BE%84%E5%88%86%E9%87%8F%22%5D%20--%3E%20DIR%5B%22%E7%9B%AE%E5%BD%95%E6%96%87%E4%BB%B6%3A%20%E5%90%8D%E5%88%B0%20inode%20%E5%8F%B7%22%5D%0A%20%20DIR%20--%3E%20INO%5B%22inode%3A%20%E5%85%83%E6%95%B0%E6%8D%AE%E4%B8%8E%E5%9D%97%22%5D%0A%20%20INO%20--%3E%20BLK%5B%22%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>名字与对象分离，删除名字只减链接；管道与设备也可以有 inode，于是「一切皆文件」有落点。mmap 与 <code>read</code> 都经 inode 找页或块。<a href="/cs/demand-paging">按需调页</a>读文件时，缺的是 inode 指向的块，不是目录字符串。</p><p>目录也是文件，所以目录也可被 <code>read</code>（历史上）；现代接口用 <code>getdents</code>。循环目录（错误的 <code>..</code>）由工具检测，内核在 <code>rename</code> 时避免把目录挂到自己的子孙下。</p><p>删除一个名字时，两种链接的命运为何不同：</p>',4)),(a(),n(t,null,{default:E(()=>[B(d,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22unlink%20%E4%B8%80%E4%B8%AA%E5%90%8D%E5%AD%97%22%5D%20--%3E%20H%7B%22%E8%BF%99%E6%9D%A1%E7%9B%AE%E5%BD%95%E9%A1%B9%E6%8C%87%E5%90%91%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20H%20--%20%22%E7%A1%AC%E9%93%BE%E6%8E%A5%EF%BC%9A%E7%9B%B4%E6%8E%A5%E6%8C%87%20inode%22%20--%3E%20C1%5B%22inode%20%E9%93%BE%E6%8E%A5%E8%AE%A1%E6%95%B0%E5%87%8F%E4%B8%80%22%5D%0A%20%20C1%20--%3E%20C2%7B%22%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%EF%BC%9F%22%7D%0A%20%20C2%20--%20%22%E5%90%A6%22%20--%3E%20K%5B%22%E5%86%85%E5%AE%B9%E8%BF%98%E5%9C%A8%EF%BC%8C%E5%85%B6%E5%AE%83%E5%90%8D%E5%AD%97%E7%85%A7%E5%B8%B8%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20C2%20--%20%22%E6%98%AF%22%20--%3E%20OP%7B%22%E8%BF%98%E6%9C%89%E8%BF%9B%E7%A8%8B%E6%89%93%E5%BC%80%EF%BC%9F%22%7D%0A%20%20OP%20--%20%22%E6%98%AF%22%20--%3E%20HOLD%5B%22%E6%95%B0%E6%8D%AE%E6%9A%82%E7%95%99%EF%BC%8Cfd%20%E5%85%A8%E5%85%B3%E5%86%8D%E5%9B%9E%E6%94%B6%22%5D%0A%20%20OP%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E5%9B%9E%E6%94%B6%20inode%20%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A%20%20H%20--%20%22%E7%AC%A6%E5%8F%B7%E9%93%BE%E6%8E%A5%EF%BC%9A%E5%AD%98%E8%B7%AF%E5%BE%84%E7%9A%84%E5%B0%8F%E6%96%87%E4%BB%B6%22%20--%3E%20BR%5B%22%E7%9B%AE%E6%A0%87%E5%B7%B2%E5%88%A0%E5%88%99%E9%93%BE%E6%8E%A5%E6%82%AC%E7%A9%BA%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">常见误区：初学者容易以为 <code>rm</code> 之后磁盘空间立刻释放。实际 unlink 只减链接计数；若有进程还握着这个文件的打开描述符，块照样不回收，直到最后一个描述符关闭——日志程序能安全「删了再写新文件」，靠的正是这一点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 inode 与 NTFS MFT 做成对照表，不引入扩展属性的全部命名空间。也不把崩溃时 inode 与目录项谁先落盘写完——那是日志与后课缓冲的接头，数据库栏已有 WAL，本课文件系统只点「元数据也要一致」。</p><p>符号链接有深度上限，防止环。权限沿路径每一目录的搜索位检查，最后才看目标 inode 的读位。</p><p>设备号加 inode 号在一台机器上标识对象；跨 NFS 的标识另有文件句柄。</p><p>后课默认：路径终于 inode，字节在块里。内存与磁盘之间那层缓存，以及脏了何时写，后课缓冲与脏页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>inode 是元数据与块指针；目录是名字到 inode 号的文件。</li><li>硬链接共享 inode；打开抓住对象不抓住路径。</li><li>块缓存与脏写回是后课。</li><li>出处：Thompson, UNIX Implementation；Bach, <em>UNIX</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const T=r(l,[["render",c]]);export{F as __pageData,T as default};
